resource "aws_s3_bucket" "lake" {
  bucket = "acme-data-lake-prod"
  tags = {
    team        = "data-platform"
    environment = "prod"
    cost_center = "CC-204"
    managed_by  = "terraform"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "lake" {
  bucket = aws_s3_bucket.lake.id

  # Warm curated data: let S3 auto-tier based on access patterns
  rule {
    id     = "curated-intelligent-tiering"
    status = "Enabled"
    filter { prefix = "curated/" }
    transition {
      days          = 0
      storage_class = "INTELLIGENT_TIERING"
    }
  }

  # Raw landing data: age it down explicitly, it is rarely re-read
  rule {
    id     = "raw-tier-down-and-expire"
    status = "Enabled"
    filter { prefix = "raw/" }
    transition {
      days          = 30
      storage_class = "STANDARD_IA"    # infrequent access after 30d
    }
    transition {
      days          = 90
      storage_class = "GLACIER"        # deep cold after 90d
    }
    expiration {
      days = 730                        # delete raw after 2 years
    }
  }

  # Clean up incomplete multipart uploads (silent cost sink)
  rule {
    id     = "abort-incomplete-mpu"
    status = "Enabled"
    filter {}
    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  # Expire old object versions to control versioning cost
  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"
    filter {}
    noncurrent_version_expiration {
      noncurrent_days = 60
    }
  }
}
